def match(orders):
    import heapq
    trades = []
    book = {}  # id -> dict(side, price, qty, active, time)
    buy_heap = []   # max-heap by price (store -price), then time
    sell_heap = []  # min-heap by price, then time

    for t, o in enumerate(orders):
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = book.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
            is_market = False
        elif typ == 'ioc':
            _, oid, side, price, qty = o
            is_market = False
        else:  # market
            _, oid, side, qty = o
            price = None
            is_market = True

        remaining = qty

        if side == 'buy':
            opp = sell_heap
        else:
            opp = buy_heap

        while remaining > 0 and opp:
            top = opp[0]
            oid2 = top[2]
            info2 = book.get(oid2)
            if info2 is None or not info2['active'] or info2['qty'] <= 0:
                heapq.heappop(opp)
                continue
            resting_price = info2['price']
            if not is_market:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            trade_qty = min(remaining, info2['qty'])
            if side == 'buy':
                trades.append([oid, oid2, resting_price, trade_qty])
            else:
                trades.append([oid2, oid, resting_price, trade_qty])

            remaining -= trade_qty
            info2['qty'] -= trade_qty
            if info2['qty'] == 0:
                info2['active'] = False
                heapq.heappop(opp)

        if typ == 'limit':
            book[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'active': remaining > 0,
                'time': t
            }
            if remaining > 0:
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, t, oid))
                else:
                    heapq.heappush(sell_heap, (price, t, oid))
        else:
            # ioc or market: leftover discarded, but record for cancel no-op purposes
            book[oid] = {
                'side': side,
                'price': price,
                'qty': 0,
                'active': False,
                'time': t
            }

    return trades

